package palindrome

import (
	"errors"
	"fmt"
)

// Product holds a palindromic product and all factor pairs within the range.
type Product struct {
	Value         int
	Factorizations [][2]int
}

func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if max.Value < product {
				max = Product{product, [][2]int{{i, j}}}
			} else if max.Value == product {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
			if min.Value == 0 || min.Value > product {
				min = Product{product, [][2]int{{i, j}}}
			} else if min.Value == product {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
		}
	}

	if max.Value == 0 {
		return Product{}, Product{}, errors.New("no palindromes found")
	}
	return min, max, nil
}
```

Wait — the problem: min.Value == 0 as a sentinel. Can a valid palindrome product be 0? If fmin=0, then 0*0=0 is a palindrome. But the test cases don't include 0. The commented-out bonus tests do include 0, but they're commented out. The instructions say "do not modify tests". The active test cases are fmin>=1. But for safety, should we use a boolean flag instead of 0-sentinel? Hmm, but the zero-value Product{} is used to mean "skip test" — the test checks `len(want.Factorizations) > 0` to decide whether to test. So if we return a zero-value Product when there are no palindromes, the test is skipped. Using a boolean flag internally is cleaner.

Actually, wait, there's a subtle point with the min sentinel: if the range includes 0, product 0 is a palindrome, and min should be 0. With the 0-sentinel approach, `min.Value == 0 || min.Value > product` — the first time we find a palindrome product p, if p > 0, then min.Value == 0 is true, so min = p. This handles it. If p == 0, then min.Value == 0 is true, so min = Product{0, ...}. This works too. But subsequent palindromes: min.Value == 0, so `min.Value == 0 || ...` would reset min to the new product, which is wrong. So the 0-sentinel is buggy for the 0 case. For robustness, use a boolean.

