package palindrome

import (
	"errors"
	"fmt"
)

// Product is a palindromic product along with all factor pairs
// within the given range that produce it.
type Product struct {
	Value          int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products
// of two numbers within [fmin, fmax] (both inclusive), along with
// all factor pairs for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax: %d > %d", fmin, fmax)
	}

	var min, max Product
	found := false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if !found {
				min, max = Product{product, [][2]int{{i, j}}}, Product{product, [][2]int{{i, j}}}
				found = true
			} else {
				if product > max.Value {
					max = Product{product, [][2]int{{i, j}}}
				} else if product == max.Value {
					max.Factorizations = append(max.Factorizations, [2]int{i, j})
				}
				if product < min.Value {
					min = Product{product, [][2]int{{i, j}}}
				} else if product == min.Value {
					min.Factorizations = append(min.Factorizations, [2]int{i, j})
				}
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes found")
	}
	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	s := fmt.Sprintf("%d", n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
```

